import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import './addfrnds.scss';

const AddFrnds = () => {
  const { currentUser } = useContext(AuthContext);
  const [users, setUsers] = useState([]);
  const [friends, setFriends] = useState([]);
  const [pendingRequests, setPendingRequests] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!currentUser) return;

    const fetchData = async () => {
      setLoading(true);
      setError(null);
      const token = sessionStorage.getItem('token');
      if (!token) {
        setError('Please log in to view suggested friends.');
        setLoading(false);
        return;
      }

      try {
        console.log('AddFrnds: Fetching from URL: http://localhost:5000/api/users/all');
        console.log('AddFrnds: Token:', token);
        const usersRes = await axios.get('http://localhost:5000/api/users/all', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('AddFrnds: All users response:', usersRes.data);

        console.log(`AddFrnds: Fetching user data for ID: ${currentUser._id}`);
        const userRes = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('AddFrnds: User data response:', userRes.data);
        setFriends(userRes.data.friends || []);
        setPendingRequests(userRes.data.friendRequests || []);

        const filteredUsers = usersRes.data.filter(user => {
          const isCurrentUser = user._id === currentUser._id;
          const isFriend = userRes.data.friends?.some(friend => friend._id === user._id);
          const hasPendingRequest = userRes.data.friendRequests?.some(
            req => req.senderId === user._id && req.status === 'pending'
          );
          return !isCurrentUser && !isFriend && !hasPendingRequest;
        });
        console.log('AddFrnds: Filtered users:', filteredUsers);
        setUsers(filteredUsers);
        setError(null);
      } catch (err) {
        console.error('AddFrnds: Error details:', err);
        console.error('AddFrnds: Response:', err.response?.data);
        const errorMessage = err.response?.data?.message || 'Failed to load users.';
        setError(errorMessage);
        setUsers([]);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [currentUser]);

  const handleSendFriendRequest = async (userId) => {
    try {
      const token = sessionStorage.getItem('token');
      console.log(`AddFrnds: Sending friend request to user ID: ${userId}`);
      const res = await axios.post(`http://localhost:5000/api/users/${userId}/friend-request`, {}, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('AddFrnds: Friend request sent:', res.data);
      setUsers(users.filter((user) => user._id !== userId));
      alert('Friend request sent successfully!');
    } catch (err) {
      console.error('AddFrnds: Error sending friend request:', err);
      const errorMessage = err.response?.data?.message || 'Failed to send friend request.';
      setError(errorMessage);
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('AddFrnds: No profile picture provided, using fallback');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      console.log('AddFrnds: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('AddFrnds: Profile picture URL:', url);
    return url;
  };

  if (!currentUser) {
    return <div className="add-frnds">Please log in to view suggested friends.</div>;
  }

  return (
    <div className="add-frnds">
      <h3>Find Friends</h3>
      {loading && <p className="loading">Loading...</p>}
      {error && <p className="error">{error}</p>}
      {users.length === 0 && !loading && !error && (
        <p className="no-users">No users found.</p>
      )}
      <div className="users-list">
        {users.map((user) => (
          <div key={user._id} className="user-card">
            <div className="user-info">
              <img
                src={getProfilePictureUrl(user.profilePicture)}
                alt={`${user.username}'s profile`}
                className="avatar"
                onError={(e) => {
                  console.error(`AddFrnds: Image load error for ${user.username}:`, e);
                  e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                }}
              />
              <div className="details">
                <span className="username">{user.username}</span>
                <span className="name">{user.name}</span>
              </div>
            </div>
            <button
              className="add-btn"
              onClick={() => handleSendFriendRequest(user._id)}
              title={`Send friend request to ${user.username}`}
              disabled={loading}
            >
              <PersonAddIcon />
              Send Friend Request
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AddFrnds;
